    // Russian-loan-cat minority langs (audit §10)
    evn: 'broad', eve: 'broad', yrk: 'broad', kca: 'broad',
    niv: 'broad', ket: 'broad', mns: 'broad',
    // Lakota/Dakota/Navajo (audit §19/§20 — IPA + orthographic accents)
