// === Audit Task 194: backfill wordEvidence.formType for multi-word surface cells ===
// Auto-tag any cell whose surface contains internal whitespace. 'compound' is the
// default; hello/thanks are 'greeting-formula' / 'thanks-formula'. Auto-tagged
// entries get evidence: 'inferred' so they don't get counted as substantive
// review evidence by the Task 172 reviewStatus heuristic below.
{
    const conceptToFormType = { hello: 'greeting-formula', thanks: 'thanks-formula' };
    for (const code of Object.keys(LANG_DATA)) {
        const lang = LANG_DATA[code];
        if (!lang || !lang.words) continue;
        if (!lang.wordEvidence) lang.wordEvidence = {};
        const we = lang.wordEvidence;
        for (const k of Object.keys(lang.words)) {
            if (we[k] && we[k].formType) continue;  // explicit override wins
            const cell = lang.words[k];
            if (!Array.isArray(cell)) continue;
            const surface = cell[0];
            if (typeof surface !== 'string' || surface === '—') continue;
            if (!/\s/.test(surface)) continue;
            if (!we[k]) we[k] = { evidence: 'inferred', autoTag: 'task-194-multi-word' };
            we[k].formType = conceptToFormType[k] || 'compound';
        }
    }
}

// === Audit Task 172: backfill reviewStatus for all remaining rows ====
// Runs AFTER SOURCE_BACKFILL and Task 194 auto-tagging.
//   - wordEvidence ≥ 5 *substantive* cells AND meta.sources non-empty → 'source-checked'
//   - wordEvidence ≥ 1 substantive cell OR meta.sources non-empty   → 'human-reviewed'
//   - none of the above                                              → 'machine-seeded'
// "Substantive" = not auto-tagged by Task 194 (autoTag flag).
for (const code of Object.keys(LANG_DATA)) {
    const lang = LANG_DATA[code];
    if (!lang || !lang.meta || lang.meta.reviewStatus) continue;
    const we = lang.wordEvidence || {};
    let weCount = 0;
    for (const k of Object.keys(we)) {
        if (we[k] && we[k].autoTag) continue;  // skip auto-tagged formType-only entries
        weCount++;
    }
    const hasSources = lang.meta.sources && lang.meta.sources.length > 0;
    if (weCount >= 5 && hasSources) {
        lang.meta.reviewStatus = 'source-checked';
    } else if (weCount > 0 || hasSources) {
        lang.meta.reviewStatus = 'human-reviewed';
    } else {
        lang.meta.reviewStatus = 'machine-seeded';
    }
}

// === Audit Task 190: backfill meta.vitality from speaker count + dataStatus ===
// Heuristic: extinct/historical/proto rows → 'extinct'; otherwise scale by L1 count.
// Runtime initializer; explicit meta.vitality on a row overrides the heuristic.
{
    const dso = (typeof DATA_STATUS_OVERRIDES !== 'undefined') ? DATA_STATUS_OVERRIDES : {};
    function parseSpeakerCount(s) {
        if (typeof s !== 'string') return null;
        // Look for the first number-with-unit. Handles ~125M / "125 million" / "1.5K" etc.
        const m = s.match(/(?:~|≈|<|>|≥|≤)?\s*([\d.]+)\s*([KMB]|million|billion|thousand)?/i);
        if (!m) return null;
        let n = parseFloat(m[1]);
        if (!Number.isFinite(n)) return null;
        const unit = (m[2] || '').toLowerCase();
        if (unit === 'k' || unit === 'thousand') n *= 1e3;
        else if (unit === 'm' || unit === 'million') n *= 1e6;
        else if (unit === 'b' || unit === 'billion') n *= 1e9;
        return n;
    }
    function vitalityFromCount(n) {
        if (n === null || !Number.isFinite(n)) return 'unknown';
        if (n < 100) return 'critically-endangered';
        if (n < 1000) return 'severely-endangered';
        if (n < 10000) return 'definitely-endangered';
        if (n < 100000) return 'vulnerable';
        return 'safe';
    }
    for (const code of Object.keys(LANG_DATA)) {
        const lang = LANG_DATA[code];
        if (!lang || !lang.meta || lang.meta.vitality) continue;
        const m = lang.meta;
        const status = m.dataStatus || dso[code] || 'modern';
        if (status !== 'modern') {
            m.vitality = 'extinct';
            continue;
        }
        // Modern: parse speaker count. Look for "extinct" or "fluent" prose first.
        const sp = (m.speakers || '').toLowerCase();
        if (/extinct/.test(sp)) { m.vitality = 'extinct'; continue; }
        if (/critically endangered/.test(sp)) { m.vitality = 'critically-endangered'; continue; }
        if (/severely endangered/.test(sp)) { m.vitality = 'severely-endangered'; continue; }
        if (/definitely endangered/.test(sp)) { m.vitality = 'definitely-endangered'; continue; }
        if (/vulnerable/.test(sp)) { m.vitality = 'vulnerable'; continue; }
        const n = parseSpeakerCount(m.speakers || '');
        m.vitality = vitalityFromCount(n);
    }
}

// === Audit Task 193: backfill meta.textDirection: 'rtl' for RTL-script rows ===
// Detect RTL by checking if any surface form contains characters from RTL Unicode
// blocks (Hebrew, Arabic, Syriac, Thaana, NKo, Samaritan, Mandaic, Arabic Presentation Forms).
// Set textDirection: 'rtl' so UI rendering can use proper bidi behavior. LTR rows
// remain unset (default 'ltr').
{
    const RTL_RE = /[֐-׿؀-ۿ܀-ݏݐ-ݿހ-޿߀-߿ࠀ-࠿ࡀ-࡟ࢠ-ࣿﭐ-﷿ﹰ-﻿]/;
    for (const code of Object.keys(LANG_DATA)) {
        const lang = LANG_DATA[code];
        if (!lang || !lang.meta || lang.meta.textDirection) continue;
        const w = lang.words || {};
        let isRtl = false;
        for (const k of Object.keys(w)) {
            if (Array.isArray(w[k]) && typeof w[k][0] === 'string' && RTL_RE.test(w[k][0])) { isRtl = true; break; }
        }
        if (isRtl) lang.meta.textDirection = 'rtl';
    }
}

// === Audit Task 162: backfill meta.unattestedReason for all `—` cells ===
// For each `—` cell, set meta.unattestedReason[concept] from defaults if not
// already set. Languages can override via explicit assignment in their meta.
for (const code of Object.keys(LANG_DATA)) {
    const lang = LANG_DATA[code];
    if (!lang || !lang.meta) continue;
    const w = lang.words || {};
    let dashCells = [];
    for (const k of Object.keys(w)) {
        if (Array.isArray(w[k]) && w[k][0] === '—') dashCells.push(k);
    }
    if (dashCells.length === 0) continue;
    if (!lang.meta.unattestedReason) lang.meta.unattestedReason = {};
    for (const concept of dashCells) {
        if (!lang.meta.unattestedReason[concept]) {
            lang.meta.unattestedReason[concept] = UNATTESTED_REASON_DEFAULTS[concept] || 'unknown';
        }
    }
}

// === scriptTags (Audit Task 130) ===================================
// Audit Task 192 (2026-05-07): SCRIPT_TAGS runtime overlay migrated to
