LANG_DATA["swb"].meta = { family:"Niger-Congo (Bantu, Sabaki)", speakers:"80,200-152,000 (primarily Mayotte)", countries:"Mayotte", official:"Vernacular/regional language; French is sole official language of Mayotte", script:"Latin (official since 2006); Arabic (official since 2020)", scriptTags:['Latin'], dataStatus:'fragmentary', description:{en:"Maore Comorian (Shimaore), code swb, is a Bantu (Sabaki) language spoken primarily in Mayotte by approximately 80,200-152,000 native speakers. It is one of four mutually intelligible Comorian dialects (along with Shingazidja, Shindzwani, and Shimwali). The language features a 5-vowel system [i,e,a,o,u] and implosive consonants [ɓ,ɗ] distinctive from stops [b,d]. Official orthographies in both Latin and Arabic scripts were adopted in 2006 and 2020 respectively. The vocabulary provided reflects Pr [Provisional - limited documentation; readings pending native-speaker verification.]"} };
