LANG_DATA["ake"].meta = { family:"Cariban", speakers:"5,000-6,380 speakers. Approximately 4,500 in Guyana (Mazaruni River), 1,700 in Brazilian R", countries:"", official:"Not official. Classified as Definitely Endangered (Guyana/Venezuela) and Vulnerable (Brazil) by UNESCO Atlas of World Languages in", script:"Latin alphabet with diacritical marks. Uses: ï (dark i), ö (rounded u)", scriptTags:['Latin'], dataStatus:'fragmentary', description:{en:"Akawaio is a Cariban language (ISO 639-3: ake; Glottolog: akaw1239) spoken in Guyana, Brazil, and Venezuela. Primary territory: Mazaruni River Basin (Pakaraima Mountains), coordinates 5°10' to 6°N, 60° to 61°20'W. Endonym: Kapon (sky people). Closely related to Macushi and Patamona. Agglutinative language with SOV word order. Phonology: ~18-20 consonants, 7 vowels including nasals and affricates. Notable allophones: /k/→[ʔ], /s/→[tʃ], /n/→[ŋ]. Comprehensive bilingual dictionary compiled by Ray a"} };
LANG_DATA["aoc"].meta = { family:"Cariban", speakers:"~35,000-45,000 (UNESCO: ~35K; primarily Gran Sabana region, Venezuela)", countries:"", official:"Recognized in Venezuela's Constitution as indigenous language; not official language but constitutionally protected", script:"Romanized Latin script (practical orthography for documentation and ed", scriptTags:['Latin'], dataStatus:'fragmentary', description:{en:"Cariban language family (Northern Cariban branch). Spoken in Gran Sabana region of Canaima National Park, Bolívar state, Venezuela, with smaller populations in Guyana and Brazil. Vocabulary items reflect documented Pemón orthography; IPA transcription represents practical phonetic rendering of documented forms. Data compiled from linguistic documentation of Cariban languages; native speaker verification recommended for precision. Population and official recognition status current as of 2024-2025 [Provisional - limited documentation; readings pending native-speaker verification.]"} };
LANG_DATA["gun"].meta = { family:"Tupian (Tupí-Guaraní)", speakers:"Approximately 15,050 native speakers (2007-2008 census). Geographic distribution: Brazil ~", countries:"", official:"Stable indigenous language with no official co-status. Recognized as cultural heritage by Brazil's IPHAN (Institute of National Hi", script:"Latin alphabet (Achegety) with 33 letters: A, Ã, CH, E, Ẽ, G, G̃, H, I", scriptTags:['Latin'], dataStatus:'fragmentary', description:{en:"ISO 639-3 code: gun. Endonym: Mbyá (sometimes Nhandeva \"us/our people\"). Tupi-Guarani language family. 75% lexically similar to Paraguayan Guaraní. Geographic coordinates approximate central territory in Atlantic Forest region spanning Paraguay-Brazil-Argentina border area (centered near Misiones Province coordinates ~-27.4, -55.5). Language has 5-vowel system /a e i o u/ with contrastive nasal counterparts. Status: Stable but vulnerable per UNESCO; children still acquire as first language in ho [Provisional - limited documentation; readings pending native-speaker verification.]"} };

LANG_DATA["bla"].meta = { family:"Algonquian", speakers:"13,500–15,000 L1 and L2 speakers combined (estimate 2020s)", countries:"", official:"Recognized indigenous language in Alberta and Montana; no official status at provincial/state/federal level", script:"Latin (modern orthography developed by linguists and community; tradit", scriptTags:['Latin'], dataStatus:'fragmentary', description:{en:"Blackfoot (Siksiká Iʼksistamiʼkssin or Nitsitapiʼkssin, literally 'real language of the Niitsítapi') is an Algonquian language spoken by ~13,500 individuals across three tribes (Siksika, Kainai, Piikani) in Alberta (Canada) and Montana (USA). Characterized by an impressive array of consonants and a relatively simple vowel system. Many concept words for 'hello', 'thanks', and 'love' are undocumented in standard lexicographic sources and represented as '—'. The orthography refl [Provisional - limited documentation; pending native-speaker verification.]"} };
