LANG_DATA["one"].meta = { family:"Iroquoian", speakers:"~100-200 fluent L1 speakers (critically endangered); several hundred heritage learners thr", countries:"", official:"Recognized by Oneida Nation (tribal sovereign entity in USA and Canada); no official recognition by US federal government or Canad", script:"Latin alphabet with diacritics (apostrophes for glottal stops ʔ, schwa", scriptTags:['Latin'], dataStatus:'fragmentary', description:{en:"Oneida (Onʌyota'káhkahʌ, \"People of the Standing Stone\") is a Northern Iroquoian language historically spoken in the Finger Lakes region of New York. It is one of the Six Nations (later Haudenosaunee Confederacy) languages. Currently spoken by ~100-200 fluent elders and several hundred heritage learners at Oneida Nation (New York), Oneida Nation (Wisconsin), and Six Nations of the Grand River (Ontario). The language is critically endangered but has active revitalization throu [Provisional - limited documentation; pending native-speaker verification.]"} };
LANG_DATA["ono"].meta = { family:"Iroquoian", speakers:"approximately 50 fluent native speakers (mostly elderly), with revitalization efforts prod", countries:"", official:"Not official language; used ceremonially in Onondaga Nation governance and law presentation; integral to religious, political and ", script:"Latin alphabet with diacritical marks (ogoneks, tildes, acute accents,", scriptTags:['Latin'], dataStatus:'fragmentary', description:{en:"Onondaga (code: ono; ISO 639-3: ono) is a Northern Iroquoian language of the Haudenosaunee Confederacy. Endonym: Onoñdaʼgegáʼ nigaweñoʼdeñʼ (literally \"Onondaga is our language\"). Territory coordinates approximately center on Onondaga reservation south of Syracuse, New York (42.95°N, 76.20°W). Primary speakers are elderly in both locations; language classified as Critically Endangered with ~80% certainty. Revitalization active since 2010 via Onondaga Nation Language Center an [Provisional - limited documentation; pending native-speaker verification.]"} };
LANG_DATA["win"].meta = { family:"Siouan", speakers:"Approximately 40 fluent native speakers (all elders); approximately 250 L1 speakers as of ", countries:"", official:"Severely Endangered (UNESCO); not an official language of any jurisdiction; extensively revitalized through Ho-Chunk Nation educat", script:"Latin alphabet-based, derived from Americanist IPA (adopted 1994 by Ho", scriptTags:['Latin'], dataStatus:'fragmentary', description:{en:"Endonym: Hoocąk or Hocąk (lit. \"People/voice of the Sacred/Big [first]\"). ISO 639-3 code: win. Language family: Siouan (Western Siouan, Mississippi Valley Siouan, Chiwere-Winnebago). Territory: Wisconsin (14 counties), Nebraska (Winnebago Reservation), Iowa, Minnesota, Illinois (historical/current distribution). Headquarters: Black River Falls, Jackson County, Wisconsin. Dialect variation: Wisconsin and Nebraska dialects differ in orthographic representation of vowel length.  [Provisional - limited documentation; pending native-speaker verification.]"} };
